  extras: [
    { id: 'v_l13_1', type: 'video', icon: '🎥', title: '고려의 건국 영상', url: 'https://www.youtube.com/results?search_query=' + encodeURIComponent('초등 5학년 사회 고려의 건국 왕건 후삼국 통일'), description: '지도서 13차시 자료 — 호족의 성장과 왕건의 후삼국 통일을 보여 주는 짧은 영상.', source: '유튜브 검색 (교사 사전 확인 권장)', fit_slides: ['motivate', 'concept'] },
    { id: 'q_l13_1', type: 'fun_question', icon: '💡', title: '더 물어보기 1', content: '「새 나라를 세우려면 무엇이 필요할까?」 지난 시간에 생각해 온 것을 말해 볼까요?', fit_slides: ['review', 'motivate'] },
    { id: 'q_l13_2', type: 'fun_question', icon: '💡', title: '더 물어보기 2', content: '외국 사람에게 우리나라를 소개할 때 왜 「한국」이 아니라 「코리아」라고 할까요?', fit_slides: ['motivate', 'real_world'] },
    { id: 'q_l13_3', type: 'fun_question', icon: '💡', title: '더 물어보기 3', content: '왕건은 수도를 철원에서 **송악(개성)**으로 옮겼어요. 왜 그랬을까요? (왕건이 송악에서 자란 호족이었어요)', fit_slides: ['concept', 'offline_activity'] },
    { id: 'q_l13_4', type: 'fun_question', icon: '💡', title: '더 물어보기 4', content: '왕건의 무덤 근처에서 나온 청동상은 왕건이 **황제의 관**을 쓴 모습이에요. 그때 고려 사람들은 왕건을 어떻게 여겼을까요?', fit_slides: ['concept'] },
    { id: 'x_l13_1', type: 'misconception', icon: '⚠️', title: '헷갈리는 생각 1', content: '고려는 신라와 후백제만 합쳤다 — 알맞지 않아요. 발해 유민까지 받아들여 하나로 모았어요(교과서 꼭 기억해요 2).', fit_slides: ['misconception', 'basic_problem'] },
    { id: 'x_l13_2', type: 'misconception', icon: '⚠️', title: '헷갈리는 생각 2', content: '왜 「고구려」가 아니라 「고려」일까요? 고구려도 가장 힘셀 무렵 뒤로는 나라 이름을 고려라고 썼어요. 그래서 왕건도 고려라 했어요(지도서 111쪽).', fit_slides: ['concept'] },
    { id: 'c_l13_1', type: 'checklist', icon: '✅', title: '다음 차시 준비', content: '「옛날 사람들은 모두 같은 생활을 했을까?」를 한 줄로 생각해 오기.', fit_slides: ['next_lesson'] },
    { id: 't_l13_1', type: 'tip', icon: '🧩', title: '「코리아」 실마리', content: '교과서 46쪽 서양 옛 세계 지도에서 우리나라(COREA)와 동해(Sea of Corea)를 찾아보게 하세요.', fit_slides: ['motivate'] },
    { id: 't_l13_2', type: 'tip', icon: '🧩', title: '세 나라 칠판', content: '칠판을 후백제·후고구려·신라 세 칸으로 나누고, 세운 사람과 수도를 붙이게 하세요.', fit_slides: ['concept'] },
    { id: 't_l13_3', type: 'tip', icon: '🧩', title: '스스로 이룬 통일', content: '신라의 삼국 통일은 바깥 나라의 힘을 빌렸지만, 고려는 스스로의 힘으로 통일하고 발해 유민까지 품었다는 점을 짚어 주세요(지도서 111쪽).', fit_slides: ['concept', 'leveled_problem'] },
    { id: 't_l13_4', type: 'tip', icon: '🧩', title: '지도 활동 답', content: '건국 → 수도 옮김 → 신라의 항복 → 후백제를 물리침 차례로 놓았는지 확인하세요(지도서 116쪽 예시 답안). 연도는 묻지 않아요.', fit_slides: ['offline_activity'] },
    { id: 't_l13_5', type: 'tip', icon: '🧩', title: '그날의 선택 운영', content: '먼저 손을 들어 ①·② 수를 세고, 까닭을 두세 명 들은 뒤 「그때 실제로는」을 공개하세요. 너그러움이 사람들의 마음을 모은 점을 짚어 주세요.', fit_slides: ['advanced_problem'] },
    { id: 'r_l13_1', type: 'real_world', icon: '🌍', title: '우리 주변의 KOREA 찾기', content: '여권, 운동복, 물건 상자 같은 곳에서 KOREA를 찾아보고 「고려」와 소리가 닮았는지 말해 봐요.', fit_slides: ['real_world', 'summary'] },
    { id: 'r_l13_2', type: 'real_world', icon: '🌍', title: '지명에 남은 고려', content: '개성, 철원, 평양(서경) 같은 지명이 오늘 지도에서 어디인지 찾아봐요.', fit_slides: ['real_world', 'summary'] },
    { id: 'g_l13_1', type: 'game', icon: '🎮', title: '사건 카드 줄 세우기', content: '후삼국 성립 · 고려 건국 · 신라의 항복 · 후백제를 물리침 카드를 섞어 모둠별로 빠르게 차례대로 세워요.', fit_slides: ['leveled_problem', 'self_assessment'] },
    { id: 'e_l13_1', type: 'example', icon: '📝', title: '훈요 10조로 짐작하기', content: '훈요 10조 네 가지(불교·서경·우리 제도·농민 부담)를 보고 왕건이 바란 고려의 모습을 「보기」에서 골라 짝짓게 합니다(교과서 48쪽).', fit_slides: ['concept', 'basic_problem'] },
    { id: 'e_l13_2', type: 'example', icon: '📝', title: '고려 주제 표 시작', content: '「고려 사회와 사람들의 생활」 표를 새로 만들고 첫 칸에 세운 사람·통일 과정·왕건의 정책을 채우게 하세요.', fit_slides: ['self_assessment'] }
  ]
